        if new_tree is None:
            continue
        lines = new_src.split("\n")
        top = next(n for n in new_tree.body if isinstance(n, (ast.Import, ast.ImportFrom)) and ast.unparse(n) == stmt)
        return "\n".join(lines[:top.lineno - 1] + lines[top.end_lineno or top.lineno:])
