# ------------------------------------------------------------------------------------------------ helpers

def _used_names(tree: ast.AST, skip: Optional[ast.AST] = None) -> set[str]:
    out: set[str] = set()
    for n in ast.walk(tree):
        if skip is not None and n is skip:
            continue
        if isinstance(n, ast.Name):
